34			OpenWeatherAPIKey:  env("OPENWEATHER_API_KEY", ""),
35			TelegramBaseURL:    env("TELEGRAM_BASE_URL", defaultTelegramBaseURL),
36			OpenWeatherBaseURL: env("OPENWEATHER_BASE_URL", defaultOpenWeatherBaseURL),
37		}
38	
39		switch {
40		case cfg.TelegramBotToken == "":
41			errs = append(errs, errors.New("TELEGRAM_BOT_TOKEN is required"))
42		case !validBotToken(cfg.TelegramBotToken):
43			errs = append(errs, errors.New("TELEGRAM_BOT_TOKEN has invalid format, want <digits>:<secret>"))
44		}
45		if cfg.OpenWeatherAPIKey == "" {
46			errs = append(errs, errors.New("OPENWEATHER_API_KEY is required"))
47		}
48		if err := validateBaseURL(cfg.TelegramBaseURL); err != nil {
49			errs = append(errs, fmt.Errorf("TELEGRAM_BASE_URL: %w", err))
50		}
51		if err := validateBaseURL(cfg.OpenWeatherBaseURL); err != nil {
52			errs = append(errs, fmt.Errorf("OPENWEATHER_BASE_URL: %w", err))
53		}
54		level, err := parseLevel(env("LOG_LEVEL", defaultLogLevel))
55		if err != nil {
56			errs = append(errs, fmt.Errorf("LOG_LEVEL: %w", err))
57		}
58		cfg.LogLevel = level
59	
60		if err := errors.Join(errs...); err != nil {
61			return Config{}, err
62		}
63		return cfg, nil
64	}
