66	// env возвращает значение переменной без пробелов по краям или def, если она пуста.
67	func env(key, def string) string {
68		if v := strings.TrimSpace(os.Getenv(key)); v != "" {
69			return v
70		}
71		return def
72	}
73	
74	func validateBaseURL(raw string) error {
75		u, err := url.Parse(raw)
76		if err != nil {
77			return fmt.Errorf("parse url: %w", err)
78		}
79		if u.Scheme != "http" && u.Scheme != "https" {
80			return fmt.Errorf("scheme must be http or https, got %q", u.Scheme)
81		}
82		if u.Host == "" {
83			return errors.New("host is empty")
84		}
85		if u.RawQuery != "" || u.Fragment != "" {
86			return errors.New("query and fragment are not allowed")
87		}
88		return nil
89	}
90	
91	func parseLevel(s string) (slog.Level, error) {
92		switch strings.ToLower(s) {
93		case "debug":
94			return slog.LevelDebug, nil
95		case "info":
96			return slog.LevelInfo, nil
97		case "warn":
98			return slog.LevelWarn, nil
99		case "error":
100			return slog.LevelError, nil
101		default:
102			return slog.LevelInfo, fmt.Errorf("unknown level %q, want debug, info, warn or error", s)
103		}
104	}
105	
106	// validBotToken проверяет формат "123456:ABC-def_123": токен встаёт в путь URL,
107	// поэтому символы вроде "/" или "?" недопустимы.
108	func validBotToken(token string) bool {
109		id, secret, ok := strings.Cut(token, ":")
110		if !ok || id == "" || secret == "" {
