115				return false
116			}
117		}
118		for _, r := range secret {
119			isAlnum := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
120			if !isAlnum && r != '_' && r != '-' {
121				return false
122			}
123		}
124		return true
