1	// Package telegram — delivery-слой: long polling Telegram Bot API и обработка команд.
2	package telegram
3	
4	import (
5		"bytes"
6		"context"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"io"
11		"net/http"
12		"net/url"
13		"strconv"
14		"strings"
15		"time"
16	)
17	
18	const (
19		maxBodyBytes    = 1 << 20 // 1 MiB
20		longPollTimeout = 30      // секунд; http.Client.Timeout должен быть больше
21	)
22	
23	// ErrUnauthorized — Telegram отверг токен бота; ретраи бессмысленны.
24	var ErrUnauthorized = errors.New("telegram bot token rejected")
25	
26	// Update — входящее обновление Bot API (нужны только сообщения).
27	type Update struct {
28		UpdateID int64    `json:"update_id"`
29		Message  *Message `json:"message"`
30	}
31	
32	// Message — входящее сообщение.
33	type Message struct {
34		Chat Chat   `json:"chat"`
35		Text string `json:"text"`
36	}
37	
38	// Chat — чат, из которого пришло сообщение.
39	type Chat struct {
40		ID int64 `json:"id"`
41	}
42	
43	// retryAfterError — Telegram попросил подождать (HTTP 429).
44	type retryAfterError struct {
45		after time.Duration
46	}
47	
48	func (e *retryAfterError) Error() string {
49		return "telegram rate limited, retry after " + e.after.String()
50	}
51	
52	// Client — минимальный клиент Telegram Bot API.
53	type Client struct {
54		baseURL    string
55		token      string
56		httpClient *http.Client
57	}
58	
59	type apiResponse struct {
60		OK          bool            `json:"ok"`
61		Result      json.RawMessage `json:"result"`
62		Description string          `json:"description"`
63		Parameters  struct {
64			RetryAfter int `json:"retry_after"`
65		} `json:"parameters"`
66	}
67	
68	type sendMessageRequest struct {
69		ChatID int64  `json:"chat_id"`
70		Text   string `json:"text"`
71	}
72	
73	// NewClient создаёт клиент. Timeout у httpClient должен превышать long-poll timeout (30 с).
74	func NewClient(baseURL, token string, httpClient *http.Client) *Client {
75		return &Client{baseURL: baseURL, token: token, httpClient: httpClient}
76	}
77	
78	// GetUpdates забирает новые сообщения через long polling.
79	func (c *Client) GetUpdates(ctx context.Context, offset int64) ([]Update, error) {
80		q := url.Values{}
81		q.Set("offset", strconv.FormatInt(offset, 10))
82		q.Set("timeout", strconv.Itoa(longPollTimeout))
83		q.Set("allowed_updates", `["message"]`)
84		var updates []Update
85		if err := c.call(ctx, http.MethodGet, "getUpdates", q, nil, &updates); err != nil {
86			return nil, fmt.Errorf("get updates: %w", err)
87		}
88		return updates, nil
89	}
90	
91	// Send отправляет plain-text сообщение (без parse_mode). Ошибка уже очищена от токена.
92	func (c *Client) Send(ctx context.Context, chatID int64, text string) error {
93		body, err := json.Marshal(sendMessageRequest{ChatID: chatID, Text: text})
94		if err != nil {
95			return fmt.Errorf("encode message: %w", err)
96		}
97		if err := c.call(ctx, http.MethodPost, "sendMessage", nil, body, nil); err != nil {
98			return fmt.Errorf("send message: %w", err)
99		}
100		return nil
101	}
102	
103	func (c *Client) call(ctx context.Context, method, apiMethod string, q url.Values, body []byte, result any) error {
104		u, err := url.Parse(c.baseURL)
105		if err != nil {
106			return fmt.Errorf("parse base url: %w", err)
107		}
108		u = u.JoinPath("bot"+c.token, apiMethod) // формат токена проверен в config
109		u.RawQuery = q.Encode()
110	
111		var reqBody io.Reader
112		if body != nil {
113			reqBody = bytes.NewReader(body)
114		}
115		req, err := http.NewRequestWithContext(ctx, method, u.String(), reqBody)
116		if err != nil {
117			return fmt.Errorf("build request: %s", c.redact(err.Error()))
118		}
119		if body != nil {
120			req.Header.Set("Content-Type", "application/json")
121		}
122		resp, err := c.httpClient.Do(req)
123		if err != nil {
124			return fmt.Errorf("do request: %s", c.redact(err.Error())) // *url.Error содержит токен в пути
125		}
126		defer resp.Body.Close()
127	
128		var r apiResponse
